SET consume_claim_hash = NULL,
    consume_claimed_at = NULL
WHERE grant_hash = #{grantHash}
  AND exchange_owner_hash = #{exchangeOwnerHash}
  AND purpose = #{purpose}
  AND expires_at <= UTC_TIMESTAMP()
  AND consume_claim_hash IS NOT NULL

mapper.select:
SELECT source_token_hash
FROM one_time_link_flow
WHERE grant_hash = #{grantHash}
  AND exchange_owner_hash = #{exchangeOwnerHash}
  AND purpose = #{purpose}
  AND expires_at > UTC_TIMESTAMP()

mapper.update:
UPDATE one_time_link_flow
SET consume_claim_hash = #{claimHash},
    consume_claimed_at = UTC_TIMESTAMP()
WHERE grant_hash = #{grantHash}
  AND exchange_owner_hash = #{exchangeOwnerHash}
  AND purpose = #{purpose}
  AND expires_at > UTC_TIMESTAMP()
  AND consume_claim_hash IS NULL

